{"compatibility":"minor","safety_note_md":"# SafeStan Safety Note

Compatibility: minor.

Protected data: `Y`.

Generated files: `model_safe.stan`, `data_safe.json`.

Changes: moved all parameter prior sampling statements before any model-block use of the corresponding parameters, including use through the transformed parameter `alpha`. Replaced `to_vector(z) ~ normal(0, 1)` with the equivalent top-level matrix sampling statement `z ~ normal(0, 1)` so the parameter prior targets the top-level parameter directly. No data changes were made; all other top-level data variables are context inputs/predictors.
","model_safe_stan":"/**
 * Schools: ranking school examination results
 * http://www.openbugs.info/Examples/Schools.html
 */
data {
  int<lower=0> N;
  int<lower=0> M;
  vector[N] LRT;
  array[N] int school;
  array[N, 3] int School_denom;
  array[N, 2] int School_gender;
  array[N, 2] int VR;
  array[N] real Y;
  array[N] int Gender;
}
parameters {
  array[8] real beta;
  real theta;
  real phi;
  matrix[3, M] z;
  vector[3] gamma;
  cholesky_factor_corr[3] L_Sigma;
  vector<lower=0>[3] sigma_Sigma;
}
transformed parameters {
  matrix[M, 3] alpha;
  alpha = transpose(rep_matrix(gamma, M)
                    + diag_pre_multiply(sigma_Sigma, L_Sigma) * z);
}
model {
  array[N] real Ymu;

  // Priors for fixed effects:
  beta ~ normal(0, 2.5);
  theta ~ normal(0, 2.5);
  phi ~ normal(0, 0.1);

  // Priors for random coefficients:
  z ~ normal(0, 1);
  // implies: alpha ~ multi_normal(gamma, CovarianceMatrix);

  // Hyper-priors:
  gamma ~ normal(0, 5);
  sigma_Sigma ~ cauchy(0, 2.5);
  L_Sigma ~ lkj_corr_cholesky(3);

  for (p in 1 : N) {
    Ymu[p] = alpha[school[p], 1] + alpha[school[p], 2] * LRT[p]
             + alpha[school[p], 3] * VR[p, 1] + beta[1] * LRT[p] * LRT[p]
             + beta[2] * VR[p, 2] + beta[3] * Gender[p]
             + beta[4] * School_gender[p, 1] + beta[5] * School_gender[p, 2]
             + beta[6] * School_denom[p, 1] + beta[7] * School_denom[p, 2]
             + beta[8] * School_denom[p, 3];
  }

  Y ~ normal(Ymu, exp(-0.5 * (theta + phi * LRT)));
}
